  and encode(sha256(convert_to(prosrc,'UTF8')),'hex')='049330d807c11f0d61ea3de962f33784851e0e5942ee488e71a5ffb25ff99dc5'
  and pg_get_userbyid(proowner)='postgres' and prosecdef and proconfig=array['search_path=""'] and proacl::text='{postgres=X/postgres}') then
  raise exception 'c6_guard_function_unreviewed:private.competency_eligible(public.applications,uuid)' using errcode='55000';end if;
 if not exists(select 1 from pg_proc where oid='exercise_ai.record_proposal(uuid,uuid,jsonb,integer)'::regprocedure
  and encode(sha256(convert_to(prosrc,'UTF8')),'hex')='e9a20dad044a8414a76f0b5faa89b4fbc4965a92f390b815fe15215a66d4703d'
  and pg_get_userbyid(proowner)='postgres' and prosecdef and proconfig=array['search_path=""'] and proacl::text='{postgres=X/postgres,authenticated=X/postgres}') then
  raise exception 'c6_guard_function_unreviewed:exercise_ai.record_proposal(uuid,uuid,jsonb,integer)' using errcode='55000';end if;
end $postflight$;
commit;
